SourceCode.Declaration:
/// <summary>
/// Expression class used to take a base64 encoded image, and add a white background.
/// </summary>
[TFMDescription("Expression used to take a base64 encoded image, and add a white background. Takes a base64 string as parameter")]
class TFMExpressionsBase64WhiteBack extends TFMExpressions
{

}

Method.Source:
public str processExpressionCommon(Common _common)
{
    DictTable dt = new DictTable(_common.tableId);
    FieldId   fieldId  = (dt != null ? dt.fieldName2Id(identifierStr(ItemId)) : 0);


    return this.processExpressionValue(fieldId ? _common.(fieldId) : '');
}

public str processExpressionValue(str _value)
{
    str base64str = '';
    System.Drawing.Image    image;
    System.Drawing.Bitmap   bmp;
    System.Drawing.Graphics g;
    int                     i, j;

    System.IO.MemoryStream ms = new System.IO.MemoryStream(System.Convert::FromBase64String(_value));

    if (!_value)
    {
        return _value;
    }

    if (ms != null)
    {
        image = System.Drawing.Image::FromStream(ms);

        bmp = new System.Drawing.Bitmap(image.Width,image.Height);
        g = System.Drawing.Graphics::FromImage(bmp);
        g.DrawRectangle(new System.Drawing.Pen(new System.Drawing.SolidBrush(System.Drawing.Color::FromArgb(255,255,255,255))), 0, 0, 250, 250);
        for (i = 0; i <image.Width; i++)
        {
            for (j= 0; j < image.Height; j++)
            {
                bmp.SetPixel(i,j,System.Drawing.Color::White);
            }
        }

        g.DrawImage(image,0,0,image.Width,image.Height);
        base64str = TFMImageHelper::Image2Base64(bmp);
    }
    else 
    {
        return _value;
    }
    return base64str;
}
